script:
var doc = Document;
// Goal: load a family into the project in the same run as a write.
// Rule: LoadFamily, Document.Export, UIDocument.RequestViewChange and
// EditScope.Start/Commit run their OWN transaction and refuse a target that is
// modifiable. Between blocks nothing is open, so they work at top level; inside a
// Connector.WithTransaction block the target is modifiable and Revit refuses.
// Shape: block -> self-transacting call at top level -> block.

// 1. Build a family to load: a new family document from the install's Generic
//    Model template, its geometry written inside a block ON THAT document.
var app = UIApplication.Application;
string template = null;
foreach (var f in System.IO.Directory.EnumerateFiles(app.FamilyTemplatePath, "Generic Model.rft", System.IO.SearchOption.AllDirectories)) { template = f; break; }
if (template == null) throw new System.Exception("no Generic Model.rft under Application.FamilyTemplatePath");
var fam = Connector.CreateFamilyDocument(template);
// The family document is headless and stays open after the run: return its title
// and close it by title in a later run (documents-create-write-and-close). The
// "cleanup-title=" line below is the repo sweep's convention only.
System.Console.WriteLine("cleanup-title=" + fam.Title + ";");
string familyDocTitle = fam.Title;
Connector.WithTransaction(fam, () => {
  var plane = Autodesk.Revit.DB.Plane.CreateByNormalAndOrigin(Autodesk.Revit.DB.XYZ.BasisZ, Autodesk.Revit.DB.XYZ.Zero);
  var sketchPlane = Autodesk.Revit.DB.SketchPlane.Create(fam, plane);
  var profile = new Autodesk.Revit.DB.CurveArray();
  var p1 = new Autodesk.Revit.DB.XYZ(-1, -1, 0); var p2 = new Autodesk.Revit.DB.XYZ(1, -1, 0);
  var p3 = new Autodesk.Revit.DB.XYZ(1, 1, 0);   var p4 = new Autodesk.Revit.DB.XYZ(-1, 1, 0);
  profile.Append(Autodesk.Revit.DB.Line.CreateBound(p1, p2)); profile.Append(Autodesk.Revit.DB.Line.CreateBound(p2, p3));
  profile.Append(Autodesk.Revit.DB.Line.CreateBound(p3, p4)); profile.Append(Autodesk.Revit.DB.Line.CreateBound(p4, p1));
  var arr = new Autodesk.Revit.DB.CurveArrArray(); arr.Append(profile);
  fam.FamilyCreate.NewExtrusion(true, arr, sketchPlane, 2.0);
});

// 2. THE WRONG PLACE, caught so this run can show it: LoadFamily inside a block on
//    the TARGET. Revit throws InvalidOperationException ("must not be modifiable");
//    uncaught, the connector reports it as `script-target-must-not-be-modifiable`
//    with the remedy "move the call OUTSIDE your Connector.WithTransaction block".
string insideBlock;
try {
  Connector.WithTransaction(doc, () => { fam.LoadFamily(doc); });
  insideBlock = "accepted (unexpected)";
} catch (Autodesk.Revit.Exceptions.InvalidOperationException ex) {
  insideBlock = "refused: " + ex.Message;
}

// 3. THE RIGHT PLACE: at top level, between blocks. The target is not modifiable
//    here (IsModifiable == false), so the load commits its own transaction into
//    the run's group.
bool targetModifiableHere = doc.IsModifiable;
var family = fam.LoadFamily(doc);

// 4. Ordinary writes go back inside a block -- e.g. activate a symbol and place an
//    instance (family-instances-place-hosted shows placement). Confirming the load is a
//    READ, so it stays at top level with no block: a collector sees the family at once.
int familiesNamed = 0;
foreach (Autodesk.Revit.DB.Family f in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Family))) {
  if (f.Name == family.Name) familiesNamed++;
}

// 5. The same rule for the others, not run here:
//    - UIDocument.RequestViewChange(view): top level; refused inside a block. UIDocument
//      is null for a background/created document, so do it routed at the active one.
//    - doc.Export(folder, name, views, new DWGExportOptions()): build the view inside a
//      block, export between blocks (export-views-dwg).
//    - var scope = new StairsEditScope(doc, "..."); scope.Start(baseLevelId, topLevelId) at top level,
//      the run inside a block, scope.Commit(new FailuresPreprocessor()) at top level
//      (stairs-with-edit-scope).
//    A throw AFTER the load still undoes it: the self-transacted commit sits inside
//    the run's group, which rolls back as one.
return new {
  familyName = family.Name,
  loadedInsideBlock = insideBlock,        // "refused: ..."
  targetModifiableAtTopLevel = targetModifiableHere, // false
  familiesNamed,                          // 1
  familyDocumentStillOpen = familyDocTitle
};
